<?php require dirname(__DIR__).'/app/bootstrap.php';require_admin();$error='';$edit=(int)($_GET['id']??0);
function upload_image(string $field,string $fallback): string {return cloud_upload($field,$fallback);}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$id=(int)($_POST['id']??0);$old=$id?query('SELECT * FROM products WHERE id=?',[$id])->fetch():null;if($id&&!$old)throw new DomainException('Product not found.');$name=trim((string)($_POST['name']??''));$slug=trim((string)($_POST['slug']??''));$desc=trim((string)($_POST['description']??''));$price=(string)($_POST['price']??'');$selected=array_values(array_intersect(sizes(),$_POST['sizes']??[]));if(strlen($name)<2||strlen($name)>140||!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)||strlen($slug)>120||!ctype_digit($price)||(int)$price<1||(int)$price>1000000||!$selected||strlen($desc)>5000)throw new DomainException('Provide a name, unique URL slug, whole BDT price, description and at least one size.');if(query('SELECT id FROM products WHERE slug=? AND id<>?',[$slug,$id])->fetch())throw new DomainException('That URL slug already exists.');$stocks=[];foreach($selected as $s){$v=trim((string)($_POST['stock'][$s]??''));if($v!==''&&(!ctype_digit($v)||(int)$v>100000))throw new DomainException('Stock must be blank or a whole number from 0 to 100000.');$stocks[$s]=$v===''?null:(int)$v;}
$category=trim((string)($_POST['category']??''));if($category===''||strlen($category)>100)throw new DomainException('Enter a category of up to 100 characters.');if(strcasecmp($category,'Cargo Pants')===0)$category='Lowers';if(strcasecmp($category,'T-Shirts')===0)$category='T-shirts';if(array_sum(array_map(fn($f)=>(int)($f['size']??0),$_FILES))>3*1024*1024)throw new DomainException('Keep the combined photo upload under 3 MB.');$image=upload_image('image',$old['image']??'');if(!$image)throw new DomainException('Add a front image.');$back=upload_image('back_image',$old['back_image']??'');db()->beginTransaction();
if($id){query('SELECT id FROM products WHERE id=? FOR UPDATE',[$id]);query('UPDATE products SET slug=?,name=?,description=?,price=?,image=?,back_image=?,active=? WHERE id=?',[$slug,$name,$desc,(int)$price,$image,$back?:null,isset($_POST['active'])?1:0,$id]);}else{query('INSERT INTO products(slug,name,description,price,image,back_image,active) VALUES(?,?,?,?,?,?,?)',[$slug,$name,$desc,(int)$price,$image,$back?:null,isset($_POST['active'])?1:0]);$id=(int)db()->lastInsertId();}
query('UPDATE products SET category=? WHERE id=?',[$category,$id]);
// Preserve variants referenced by pending reservations; removed sizes are disabled with zero stock.
foreach(sizes() as $s){if(in_array($s,$selected,true))query('INSERT INTO variants(product_id,size,stock) VALUES(?,?,?) ON DUPLICATE KEY UPDATE stock=VALUES(stock)',[$id,$s,$stocks[$s]]);else query('UPDATE variants SET stock=0 WHERE product_id=? AND size=?',[$id,$s]);}db()->commit();flash('Product saved.');redirect('admin/products.php?id='.$id);
}catch(DomainException $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
$p=$edit?query('SELECT * FROM products WHERE id=?',[$edit])->fetch():null;$variants=$p?query('SELECT * FROM variants WHERE product_id=?',[$edit])->fetchAll():[];$stocks=array_column($variants,'stock','size');$products=query('SELECT * FROM products ORDER BY id DESC')->fetchAll();render_header('Products',true); ?>
<main class="page"><div class="section-head"><div><p class="eyebrow">YOUR GROWING COLLECTION</p><h1>Products.</h1></div><a class="button outline" href="<?=url('admin/products.php')?>">+ NEW PRODUCT</a></div><div class="checkout-layout"><section><h2><?=$p?'Edit product':'Add a product'?></h2><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif ?><form method="post" enctype="multipart/form-data"><?=csrf_input()?><input type="hidden" name="id" value="<?=h($p['id']??0)?>"><label>Product name<input name="name" maxlength="140" value="<?=h($p['name']??'')?>" required></label><label>URL slug<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="120" placeholder="living-tee" value="<?=h($p['slug']??'')?>" required></label><label>Price in BDT<input type="number" name="price" min="1" max="1000000" step="1" value="<?=h($p['price']??'')?>" required></label><label>Category<input name="category" list="product-categories" maxlength="100" value="<?=h($p['category']??'')?>" placeholder="Choose or type a category" required></label><datalist id="product-categories"><?php foreach(array_unique(array_merge(['T-shirts','Hoodies','Lowers'],array_filter(array_column($products,'category')))) as $category):?><option value="<?=h($category)?>"><?php endforeach ?></datalist><label>Description<textarea name="description" maxlength="5000"><?=h($p['description']??'')?></textarea></label><div class="form-grid"><label>Front image<input type="file" name="image" accept="image/png,image/jpeg,image/webp" <?=$p?'':'required'?>></label><label>Back image (optional)<input type="file" name="back_image" accept="image/png,image/jpeg,image/webp"></label></div><p class="hint">PNG, JPEG or WebP, up to 3 MB combined per save. Existing images stay when no replacement is chosen.</p><h2>Sizes & inventory</h2><p class="hint">Blank stock means inventory is not tracked. Use 0 for sold out. Enter the currently available quantity after existing orders have been reserved.</p><div class="inventory-grid"><?php foreach(sizes() as $s):?><div><label class="check-label"><input type="checkbox" name="sizes[]" value="<?=$s?>" <?=array_key_exists($s,$stocks)?'checked':''?>><?=$s?></label><input aria-label="<?=$s?> stock" type="number" min="0" max="100000" name="stock[<?=$s?>]" value="<?=h($stocks[$s]??'')?>" placeholder="Untracked"></div><?php endforeach ?></div><label class="check-label"><input type="checkbox" name="active" value="1" <?=!$p||$p['active']?'checked':''?>>Visible in shop</label><button class="button dark">SAVE PRODUCT ↗</button></form></section><aside><h2>All products</h2><?php foreach($products as $item):?><a class="bag-row" href="<?=url('admin/products.php?id='.$item['id'])?>"><img src="<?=url(h($item['image']))?>" alt=""><div><h3><?=h($item['name'])?></h3><p><?=money($item['price'])?> · <?=$item['active']?'Visible':'Hidden'?></p></div></a><?php endforeach ?></aside></div></main><?php render_footer(); ?>
